55	  var body: some View {
56	    HStack(spacing: 12) {
57	      // Path and cwd are mutually exclusive in practice — a content pane has no cwd, a terminal has
58	      // no file — so they share the leading slot, ahead of the branch.
59	      pathSegment
60	      cwdSegment
61	      branchSegment
62	      // Diagnosis sits left-aligned right after the branch, not pushed to the far edge.
63	      if let diagnosis { diagnosisSegment(diagnosis) }
64	      Spacer(minLength: 8)
65	      DetachedSessionsButton(target: target)
66	      if isRunTab, let run = runStatePresentation { runSegment(run) }
67	      if let activeAgent { agentUsageSegment(activeAgent) }
68	    }
69	    // `.subheadline` (11pt) — the middle of the two sizes this bar has worn. `.caption` (10pt) was
70	    // too small to read at a glance for what the bar carries (a pane's identity: path, branch, run
71	    // state); `.callout` (12pt) read as content rather than chrome.
72	    .font(.subheadline)
73	    .foregroundStyle(theme.tokens.fgMuted)
74	    .lineLimit(1)
75	    .padding(.horizontal, 10)
76	    // Fixed, not vertical padding: the bar's height must not vary with its content (an icon, a
77	    // `ProgressView`) or a pane would resize as a diagnosis arrives. Held at 28pt across the font
78	    // change so panes don't reflow — the 11pt text just sits in a little more air.
79	    .frame(height: 28)
80	    .frame(maxWidth: .infinity)
81	    // `panel` (bg blended 5.5% toward fg), not the raw terminal `bg`: the bar reads as chrome rather
82	    // than as more terminal. Opaque and theme-derived, so it lifts by the same amount on a light or a
83	    // dark theme — a fixed white/black wash would invert on one of them.
84	    .background(theme.tokens.panel)
85	    .overlay(alignment: .top) { theme.tokens.border.frame(height: 1) }
86	    .accessibilityElement(children: .contain)
87	    .accessibilityIdentifier("terminal.statusBar")
88	    .task(id: activeAgent) {
89	      if activeAgent != nil { agentUsage.refresh() }
90	    }
91	    .alert("Enable Claude usage?", isPresented: $confirmingClaudeUsage) {
92	      Button("Cancel", role: .cancel) {}
93	      Button("Enable") {
94	        do {
95	          try claudeUsageBridge.enable()
96	          agentUsage.refresh()
97	        } catch {
98	          claudeBridgeError = error.localizedDescription
99	        }
100	      }
101	    } message: {
102	      Text(
103	        "Workroom will update ~/.claude/settings.json to run its status-line wrapper. The wrapper "
104	          + "stores only Claude's rate_limits data, then passes the original status-line input "
105	          + "unchanged to your current command. You can disable this from Agent Settings."
106	      )
107	    }
108	    .alert("Claude usage wasn’t enabled", isPresented: bridgeErrorPresented) {
109	      Button("OK", role: .cancel) {}
110	    } message: {
111	      Text(claudeBridgeError ?? "The Claude status-line bridge could not be installed.")
112	    }
113	  }
