121	  /// True while pinned (clicked) OR hovering — a system dismissal (clicking outside the popover, or
122	  /// Escape) clears both, so a pin doesn't linger open after the platform already closed it.
123	  private var usageDetailPresented: Binding<Bool> {
124	    Binding(
125	      get: { usageDetailPinned || usageDetailHovering },
126	      set: { presented in
127	        if !presented {
128	          usageDetailPinned = false
129	          usageDetailHovering = false
130	        }
131	      })
132	  }
