136	  @ViewBuilder private func agentUsageSegment(_ backend: AgentBackend) -> some View {
137	    if backend == .claude, claudeUsageBridge.state == .disabled {
138	      Button("Enable Claude usage…") { confirmingClaudeUsage = true }
139	        .buttonStyle(StatusBarSegmentButtonStyle())
140	        .foregroundStyle(theme.tokens.accent)
141	        .help("Enable the opt-in Claude status-line bridge")
142	        .accessibilityIdentifier("terminal.statusBar.agentUsage.enableClaude")
143	    } else if let snapshot = agentUsage.snapshot(for: backend) {
144	      let label = quotaAccessibilityLabel(snapshot)
145	      Button {
146	        usageDetailPinned.toggle()
147	        // The mouse is still over the segment right after this click, so `.onHover` never fires an
148	        // exit — without this, unpinning while hovering left `usageDetailPinned || usageDetailHovering`
149	        // true and the popover never actually closed.
150	        if !usageDetailPinned { usageDetailHovering = false }
151	      } label: {
152	        ViewThatFits(in: .horizontal) {
153	          quotaFull(snapshot)
154	          quotaCompact(snapshot)
155	        }
156	        .fixedSize(horizontal: true, vertical: false)
157	      }
158	      .buttonStyle(StatusBarSegmentButtonStyle())
159	      .accessibilityElement(children: .ignore)
160	      .accessibilityLabel(label)
161	      .accessibilityIdentifier("terminal.statusBar.agentUsage")
162	      .onHover { hovering in
163	        usageHoverRevealWorkItem?.cancel()
164	        if hovering {
165	          let workItem = DispatchWorkItem { usageDetailHovering = true }
166	          usageHoverRevealWorkItem = workItem
167	          DispatchQueue.main.asyncAfter(deadline: .now() + usageHoverRevealDelay, execute: workItem)
168	        } else {
169	          usageDetailHovering = false
170	        }
171	      }
172	      .popover(isPresented: usageDetailPresented, arrowEdge: .bottom) {
173	        AgentUsageDetailView(snapshot: snapshot, now: Date())
174	          .frame(width: AgentUsageDetailView.popoverWidth)
175	      }
176	    } else {
177	      let isLoading = agentUsage.loading.contains(backend)
178	      HStack(spacing: 4) {
179	        if isLoading { ProgressView().controlSize(.mini) }
180	        Text(
181	          isLoading
182	            ? "Loading \(backend.displayName) usage…" : "\(backend.displayName) usage unavailable")
183	      }
184	      .foregroundStyle(theme.tokens.fgDim)
185	      .help("Waiting for a fresh local \(backend.displayName) quota snapshot")
186	      .accessibilityLabel(
187	        isLoading
188	          ? "Loading \(backend.displayName) quota usage"
189	          : "\(backend.displayName) quota usage unavailable"
190	      )
191	      .accessibilityIdentifier("terminal.statusBar.agentUsage.unavailable")
192	    }
193	  }
