195	  /// One concatenated `Text` (not an `HStack` of separate `Text`s, like `quotaCompact` below) because
196	  /// the pace figure needs its own color run inline within a window's segment. Shown, and colored,
197	  /// only in deficit — under-pace/on-pace is the unremarkable case and stays silent.
198	  private func quotaFull(_ snapshot: AgentQuotaSnapshot) -> Text {
199	    let now = Date()
200	    // A single window needs no "5h"/"wk" prefix to disambiguate from — there's nothing else in the
201	    // segment it could be confused with (e.g. Codex, which only ever reports one window).
202	    let showsWindowKind = snapshot.windows.count > 1
203	    return snapshot.windows.reduce(Text(snapshot.backend.displayName)) { text, window in
204	      let used = Int(window.usedPercentage.rounded())
205	      let usedText = showsWindowKind ? "\(window.kind.compactLabel) \(used)%" : "\(used)%"
206	      var windowText = Text(" · \(usedText)")
207	      let pace = window.pace(at: now)
208	      if pace.isOver {
209	        let paceText = Text(" (\(pace.compactDescription))").foregroundColor(paceColor(pace))
210	        windowText = windowText + paceText
211	      }
212	      return text + windowText
213	    }
214	  }
215	
216	  private func quotaCompact(_ snapshot: AgentQuotaSnapshot) -> some View {
217	    let showsWindowKind = snapshot.windows.count > 1
218	    return HStack(spacing: 5) {
219	      ForEach(snapshot.windows) { window in
220	        let used = Int(window.usedPercentage.rounded())
221	        Text(showsWindowKind ? "\(window.kind.compactLabel) \(used)%" : "\(used)%")
222	      }
223	    }
224	  }
225	
226	  /// Only reached for a window already confirmed `pace.isOver` (in deficit) — a deeper deficit reads
227	  /// as failure, a shallower one as warning. Independent of the popover's marker, which only
228	  /// distinguishes over/under pace, not degree.
229	  private func paceColor(_ pace: AgentPace) -> Color {
230	    pace.percentagePoints > 15 ? theme.tokens.failure : theme.tokens.warning
231	  }
232	
233	  private func quotaAccessibilityLabel(_ snapshot: AgentQuotaSnapshot) -> String {
234	    let now = Date()
235	    let windows = snapshot.windows.map { window in
236	      let used = Int(window.usedPercentage.rounded())
237	      let pace = used == 0 ? "" : ", \(window.pace(at: now).accessibilityDescription)"
238	      return
239	        "\(window.kind.compactLabel) quota \(used)% used\(pace), \(window.resetDescription(at: now))"
240	    }
241	    return "\(snapshot.backend.displayName) quota. " + windows.joined(separator: ". ")
242	  }
