244	  // MARK: File path / branch / cwd
245	
246	  /// The open file's repo-relative path (issue #136) — the pane's identity, which the tab chip can't
247	  /// carry (it shows only the basename, so two `user.rb` tabs read the same). Tooltip resolves it
248	  /// absolutely against the workroom directory.
249	  ///
250	  /// Two modifiers here are decisions, not defaults:
251	  ///
252	  /// - `.head`, unlike the `.middle` its neighbours use. A repo-relative path's discriminating part
253	  ///   is its TAIL: middle-truncating `app/models/user.rb` and `app/views/user.rb` elides exactly the
254	  ///   component that tells them apart, which is the bug this segment exists to fix. Head truncation
255	  ///   drops the shared prefix and keeps the immediate directory plus the filename.
256	  /// - `.layoutPriority(1)`, so the branch yields first when the bar is squeezed. Content panes are
257	  ///   exempt from the pane-width floor (`TerminalSessions.fits` returns true with no surface), so a
258	  ///   split diff pane can be ~198pt wide; without a priority SwiftUI shrinks both labels
259	  ///   proportionally. The path is this pane's identity, while the branch is the same on every pane
260	  ///   of the workroom and already shown in the sidebar.
261	  @ViewBuilder private var pathSegment: some View {
262	    if let filePath {
263	      Label {
264	        Text(filePath).truncationMode(.head)
265	      } icon: {
266	        Image(systemName: "doc")
267	      }
268	      .labelStyle(.titleAndIcon)
269	      .layoutPriority(1)
270	      .help((target.path as NSString).appendingPathComponent(filePath))
271	      .accessibilityLabel("File \(filePath)")
272	      .accessibilityIdentifier("terminal.statusBar.path")
273	    }
274	  }
