289	  /// The pane's cwd, and the two things you want from a path you can see: copy it, or reveal it
290	  /// (issue #143). Clicking drops the menu; the segment carries a hover well so it reads as clickable
291	  /// (the path and branch segments, which do nothing, deliberately don't).
292	  ///
293	  /// A plain `Button` popping an `NSMenu` by hand, NOT a SwiftUI `Menu`. A `Menu`'s dropped list
294	  /// inherits its TRIGGER's width, and this trigger is a whole filesystem path — so two short items
295	  /// rendered in a menu as wide as the pane. An `NSMenu` we pop ourselves sizes to its own items.
296	  /// (`.menuStyle(.borderlessButton)` wouldn't have helped either: it's AppKit-backed, never reports
297	  /// hover, so the well would be impossible.) The label stays squeezable — no `.fixedSize()` — so
298	  /// `.middle` truncation still fires in a narrow split pane.
299	  ///
300	  /// The items are a menu rather than a selectable label because `.textSelection(.enabled)` swallows
301	  /// real mouseDown, which would kill the click this segment now exists to answer.
302	  @ViewBuilder private var cwdSegment: some View {
303	    if let cwd {
304	      Button {
305	        popCwdMenu(cwd)
306	      } label: {
307	        Label {
308	          Text(Self.abbreviate(cwd)).truncationMode(.middle)
309	        } icon: {
310	          Image(systemName: "folder")
311	        }
312	        .labelStyle(.titleAndIcon)
313	        // Explicit, not inherited: a `Button`'s label doesn't pick up the bar's ambient
314	        // `foregroundStyle`, so without this the segment reads brighter than its neighbours.
315	        .foregroundStyle(theme.tokens.fgMuted)
316	      }
317	      .buttonStyle(StatusBarSegmentButtonStyle())
318	      .background(MenuAnchor(view: $cwdMenuAnchor))
319	      .help(cwd)
320	      .accessibilityLabel("Working directory \(cwd)")
321	      .accessibilityIdentifier("terminal.statusBar.cwd")
322	    }
323	  }
