325	  private func popCwdMenu(_ cwd: String) {
326	    let menu = NSMenu()
327	    menu.addItem(
328	      ClosureMenuItem(title: "Copy to Clipboard") {
329	        NSPasteboard.general.clearContents()
330	        NSPasteboard.general.setString(cwd, forType: .string)
331	      })
332	    // `activateFileViewerSelecting`, matching the wording and the File menu's own "Reveal in Finder"
333	    // (which reveals the selected target's directory the same way): the directory comes up selected in
334	    // its parent. `NSWorkspace.open` would open the folder's own window instead — a different verb
335	    // than the one this item promises.
336	    menu.addItem(
337	      ClosureMenuItem(title: "Reveal in Finder") {
338	        NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: cwd)])
339	      })
340	    // At the cursor, like a context menu — but popped out of a real view rather than the tempting
341	    // `at: NSEvent.mouseLocation, in: nil` (screen coordinates, no anchor needed). That form does
342	    // nothing at all when the click is synthesized: `StatusBarCwdUITests` clicked the segment and no
343	    // menu ever appeared. Anchored to a view it opens either way, so the cursor's screen point is
344	    // converted into the anchor's own coordinates instead.
345	    if let anchor = cwdMenuAnchor, let window = anchor.window {
346	      let inWindow = window.convertPoint(fromScreen: NSEvent.mouseLocation)
347	      menu.popUp(positioning: nil, at: anchor.convert(inWindow, from: nil), in: anchor)
348	    } else {
349	      menu.popUp(positioning: nil, at: NSEvent.mouseLocation, in: nil)
350	    }
351	  }
