353	  /// `~`-abbreviate a home-relative path; leave others untouched. Truncation is left to the label.
354	  static func abbreviate(_ path: String) -> String {
355	    let home = NSHomeDirectory()
356	    if path == home { return "~" }
357	    if path.hasPrefix(home + "/") { return "~" + path.dropFirst(home.count) }
358	    return path
359	  }
