382	  private var runStatePresentation: RunPresentation? {
383	    guard let state = store.runStates[target.id] else { return nil }
384	    switch state {
385	    case .armed:
386	      return nil
387	    case .running:
388	      return RunPresentation(
389	        icon: "play.fill", text: "Running", color: AnyShapeStyle(theme.tokens.accent))
390	    case .restarting:
391	      return RunPresentation(
392	        icon: "arrow.clockwise", text: "Restarting", color: AnyShapeStyle(theme.tokens.warning))
393	    case .stopped:
394	      switch store.runOutcomes[target.id] {
395	      case .exited(let code) where code != 0:
396	        return RunPresentation(
397	          icon: "xmark.octagon.fill", text: "Failed (exit \(code))",
398	          color: AnyShapeStyle(theme.tokens.failure))
399	      case .exited:
400	        return RunPresentation(icon: "checkmark.circle", text: "Exited", color: nil)
401	      case .failedToStart:
