433	        state: bannerState,
434	        onDiagnose: { agentManager.diagnose(tab: tabID, target: target.id) },
435	        onInsertFix: { fix in
436	          state?.view.sendText(fix)
437	          showingDiagnosis = false
438	        },
439	        onInvestigate: {
440	          _ = store.startInvestigate(bannerState: bannerState, target: target, surface: state?.view)
441	          agentManager.dismiss(tab: tabID)
442	          showingDiagnosis = false
443	        },
444	        onDismiss: {
445	          agentManager.dismiss(tab: tabID)
446	          showingDiagnosis = false
447	        }
448	      )
449	      .frame(width: 380)
450	    }
