478	/// An invisible AppKit view, laid out behind the cwd segment and handed back through a binding, so
479	/// `NSMenu.popUp(positioning:at:in:)` has a view to pop out of (issue #143) — the view-less,
480	/// screen-coordinate form of that call silently does nothing for a synthesized click.
481	///
482	/// `hitTest` returns nil so the anchor can never take the click that pops the menu, or the hover that
483	/// fills the well, from the `Button` in front of it.
484	private struct MenuAnchor: NSViewRepresentable {
485	  final class AnchorView: NSView {
486	    override func hitTest(_ point: NSPoint) -> NSView? { nil }
487	  }
488	
489	  @Binding var view: NSView?
490	
491	  func makeNSView(context: Context) -> AnchorView {
492	    let anchor = AnchorView()
493	    // Async: assigning to `@State` during `makeNSView` mutates state mid-update.
494	    DispatchQueue.main.async { view = anchor }
495	    return anchor
496	  }
497	
498	  func updateNSView(_ nsView: AnchorView, context: Context) {}
499	}
