501	/// `NSMenuItem` takes an ObjC target/action, and both cwd actions are closures.
502	private final class ClosureMenuItem: NSMenuItem {
503	  private let handler: () -> Void
504	
505	  init(title: String, handler: @escaping () -> Void) {
506	    self.handler = handler
507	    super.init(title: title, action: #selector(fire), keyEquivalent: "")
508	    target = self
509	  }
510	
511	  @available(*, unavailable)
512	  required init(coder: NSCoder) { fatalError("ClosureMenuItem is built in code, never unarchived") }
513	
514	  @objc private func fire() { handler() }
515	}
